package com.smartspend.dao;
import com.smartspend.model.Transaction; import com.smartspend.util.DatabaseConnection; import java.sql.*; import java.time.LocalDate; import java.util.*;
public class TransactionDAO {
 public List<Transaction> findByUser(int uid){return search(uid,"","","",null,null,null,null,"newest");}
 public List<Transaction> search(int uid,String text,String type,String category,LocalDate from,LocalDate to,Double min,Double max,String sort){List<Transaction> a=new ArrayList<>();StringBuilder q=new StringBuilder("SELECT t.*,c.name category_name FROM transactions t JOIN categories c ON c.id=t.category_id WHERE t.user_id=?");List<Object> v=new ArrayList<>();v.add(uid);
  if(text!=null&&!text.isBlank()){q.append(" AND (t.description LIKE ? OR c.name LIKE ? OR t.notes LIKE ?)");String s="%"+text.trim()+"%";v.add(s);v.add(s);v.add(s);} if(type!=null&&!type.isBlank()&&!type.equals("All")){q.append(" AND t.type=?");v.add(type);} if(category!=null&&!category.isBlank()&&!category.equals("All")){q.append(" AND c.name=?");v.add(category);} if(from!=null){q.append(" AND t.transaction_date>=?");v.add(from);}if(to!=null){q.append(" AND t.transaction_date<=?");v.add(to);}if(min!=null){q.append(" AND t.amount>=?");v.add(min);}if(max!=null){q.append(" AND t.amount<=?");v.add(max);}q.append(" ORDER BY ").append(sort.equals("oldest")?"t.transaction_date ASC,t.id ASC":sort.equals("highest")?"t.amount DESC":sort.equals("lowest")?"t.amount ASC":"t.transaction_date DESC,t.id DESC");
  try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(q.toString())){for(int i=0;i<v.size();i++)p.setObject(i+1,v.get(i));try(ResultSet r=p.executeQuery()){while(r.next())a.add(map(r));}}catch(SQLException e){throw new RuntimeException(e);}return a;}
 public void create(Transaction t){String q="INSERT INTO transactions(user_id,category_id,amount,type,description,transaction_date,payment_method,notes) VALUES(?,?,?,?,?,?,?,?)";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){fill(p,t);p.executeUpdate();}catch(SQLException e){throw new RuntimeException(e);}}
 public void update(Transaction t){String q="UPDATE transactions SET category_id=?,amount=?,type=?,description=?,transaction_date=?,payment_method=?,notes=? WHERE id=? AND user_id=?";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,t.getCategoryId());p.setDouble(2,t.getAmount());p.setString(3,t.getType());p.setString(4,t.getDescription());p.setDate(5,java.sql.Date.valueOf(t.getTransactionDate()));p.setString(6,t.getPaymentMethod());p.setString(7,t.getNotes());p.setInt(8,t.getId());p.setInt(9,t.getUserId());p.executeUpdate();}catch(SQLException e){throw new RuntimeException(e);}}
 public void delete(int id,int uid){String q="DELETE FROM transactions WHERE id=? AND user_id=?";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,id);p.setInt(2,uid);p.executeUpdate();}catch(SQLException e){throw new RuntimeException(e);}}
 public Map<String,Double> monthlyTotals(int uid,int year,int month){Map<String,Double> m=new LinkedHashMap<>();String q="SELECT type,SUM(amount) total FROM transactions WHERE user_id=? AND YEAR(transaction_date)=? AND MONTH(transaction_date)=? GROUP BY type";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,uid);p.setInt(2,year);p.setInt(3,month);try(ResultSet r=p.executeQuery()){while(r.next())m.put(r.getString("type"),r.getDouble("total"));}}catch(SQLException e){throw new RuntimeException(e);}return m;}
 public Map<String,Double> categoryTotals(int uid,int year,int month){Map<String,Double> m=new LinkedHashMap<>();String q="SELECT c.name,SUM(t.amount) total FROM transactions t JOIN categories c ON c.id=t.category_id WHERE t.user_id=? AND t.type='EXPENSE' AND YEAR(t.transaction_date)=? AND MONTH(t.transaction_date)=? GROUP BY c.name ORDER BY total DESC";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,uid);p.setInt(2,year);p.setInt(3,month);try(ResultSet r=p.executeQuery()){while(r.next())m.put(r.getString(1),r.getDouble(2));}}catch(SQLException e){throw new RuntimeException(e);}return m;}
 private void fill(PreparedStatement p,Transaction t)throws SQLException{p.setInt(1,t.getUserId());p.setInt(2,t.getCategoryId());p.setDouble(3,t.getAmount());p.setString(4,t.getType());p.setString(5,t.getDescription());p.setDate(6,java.sql.Date.valueOf(t.getTransactionDate()));p.setString(7,t.getPaymentMethod());p.setString(8,t.getNotes());}
 private Transaction map(ResultSet r)throws SQLException{return new Transaction(r.getInt("id"),r.getInt("user_id"),r.getInt("category_id"),r.getDouble("amount"),r.getString("type"),r.getString("description"),r.getDate("transaction_date").toLocalDate(),r.getString("payment_method"),r.getString("notes"),r.getString("category_name"));}
}
